def spiral_seen(M):
    if not M or not M[0]:
        return []
    R, C = len(M), len(M[0])
    seen = [[False] * C for _ in range(R)]
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    r = c = di = 0
    out = []
    for _ in range(R * C):
        out.append(M[r][c])
        seen[r][c] = True
        nr, nc = r + dirs[di][0], c + dirs[di][1]
        if not (0 <= nr < R and 0 <= nc < C and not seen[nr][nc]):
            di = (di + 1) % 4
            nr, nc = r + dirs[di][0], c + dirs[di][1]
        r, c = nr, nc
    return out


