vector<int> spiralSeen(vector<vector<int>>& M) {
    vector<int> out;
    if (M.empty() || M[0].empty()) return out;
    int R = M.size(), C = M[0].size();
    vector<vector<bool>> seen(R, vector<bool>(C, false));
    int dr[4] = {0, 1, 0, -1}, dc[4] = {1, 0, -1, 0};
    int r = 0, c = 0, di = 0;
    for (int k = 0; k < R * C; ++k) {
        out.push_back(M[r][c]);
        seen[r][c] = true;
        int nr = r + dr[di], nc = c + dc[di];
        if (nr < 0 || nr >= R || nc < 0 || nc >= C || seen[nr][nc]) {
            di = (di + 1) % 4;
            nr = r + dr[di]; nc = c + dc[di];
        }
        r = nr; c = nc;
    }
    return out;
}
