``` {.python .cell-code}
def spiral_ring(M):
    if not M or not M[0]:
        return []
    R, C = len(M), len(M[0])
    out = []
    for k in range((min(R, C) + 1) // 2):
        top, bottom, left, right = k, R - 1 - k, k, C - 1 - k
        for j in range(left, right + 1):
            out.append(M[top][j])
        for i in range(top + 1, bottom + 1):
            out.append(M[i][right])
        if top < bottom:
            for j in range(right - 1, left - 1, -1):
                out.append(M[bottom][j])
        if left < right:
            for i in range(bottom - 1, top, -1):
                out.append(M[i][left])
    return out


