##### Python

::: {#e616d191 .cell execution_count=41}
``` {.python .cell-code}
def diag_walk(M):
    R, C = len(M), len(M[0])
    r = c = 0
    up = True
    out = []
    for _ in range(R * C):
        out.append(M[r][c])
        if up:
            if c == C - 1:
                up = False; r += 1
            elif r == 0:
                up = False; c += 1
            else:
                r -= 1; c += 1
        else:
            if r == R - 1:
                up = True; c += 1
            elif c == 0:
                up = True; r += 1
            else:
                r += 1; c -= 1
    return out


assert diag_walk([[1, 2, 3], [4, 5, 6], [7, 8, 9]]) == [1, 2, 4, 7, 5, 3, 6, 8, 9]
assert diag_walk([[1, 2], [3, 4]]) == [1, 2, 3, 4]
for _ in range(80):
    R, C = random.randint(1, 5), random.randint(1, 5)
    M = [[a * C + b for b in range(C)] for a in range(R)]
    assert diag_walk(M) == diag_bucket(M)
```
