##### C++

```cpp
vector<int> diagWalk(vector<vector<int>>& M) {
    int R = M.size(), C = M[0].size(), r = 0, c = 0;
    bool up = true;
    vector<int> out;
    for (int k = 0; k < R * C; ++k) {
        out.push_back(M[r][c]);
        if (up) {
            if (c == C - 1) { up = false; ++r; }
            else if (r == 0) { up = false; ++c; }
            else { --r; ++c; }
        } else {
            if (r == R - 1) { up = true; ++c; }
            else if (c == 0) { up = true; ++r; }
            else { ++r; --c; }
        }
    }
    return out;
}
```

