``` {.python .cell-code}
def mirror_brute(g):
    n = len(g)
    grids = [[[int(ch) for ch in row] for row in g]]
    for _ in range(3):
        a = grids[-1]
        rot = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                rot[j][n - 1 - i] = a[i][j]
        grids.append(rot)
    total = 0
    for i in range(n):
        for j in range(n):
            k = sum(G[i][j] for G in grids)
            total += min(k, 4 - k)
    return total // 4


