void zeroesCopy(vector<vector<int>>& a) {
    int m = a.size(), n = a[0].size();
    vector<vector<int>> orig = a;
    vector<bool> zr(m, false), zc(n, false);
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            if (orig[i][j] == 0) { zr[i] = true; zc[j] = true; }
