``` {.python .cell-code}
def zeroes_mark(a):
    m, n = len(a), len(a[0])
    zfr = any(a[0][j] == 0 for j in range(n))
    zfc = any(a[i][0] == 0 for i in range(m))
    for i in range(1, m):
        for j in range(1, n):
            if a[i][j] == 0:
                a[i][0] = 0
                a[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if a[i][0] == 0 or a[0][j] == 0:
                a[i][j] = 0
    if zfr:
        for j in range(n):
            a[0][j] = 0
    if zfc:
        for i in range(m):
            a[i][0] = 0
    return a


