void zeroesMark(vector<vector<int>>& a) {
    int m = a.size(), n = a[0].size();
    bool zfr = false, zfc = false;
    for (int j = 0; j < n; ++j) if (a[0][j] == 0) zfr = true;
    for (int i = 0; i < m; ++i) if (a[i][0] == 0) zfc = true;
    for (int i = 1; i < m; ++i)
        for (int j = 1; j < n; ++j)
            if (a[i][j] == 0) { a[i][0] = 0; a[0][j] = 0; }
    for (int i = 1; i < m; ++i)
        for (int j = 1; j < n; ++j)
            if (a[i][0] == 0 || a[0][j] == 0) a[i][j] = 0;
    if (zfr) for (int j = 0; j < n; ++j) a[0][j] = 0;
    if (zfc) for (int i = 0; i < m; ++i) a[i][0] = 0;
}
