def game_of_life(board):
    m, n = len(board), len(board[0])
    for i in range(m):
        for j in range(n):
            c = 0
            for x in range(max(0, i - 1), min(m, i + 2)):
                for y in range(max(0, j - 1), min(n, j + 2)):
                    if (x, y) != (i, j):
                        c += board[x][y] & 1          # bit 0 = old state
            if c == 3 or (board[i][j] & 1 and c == 2):
                board[i][j] |= 2                      # bit 1 = new state
    for i in range(m):
        for j in range(n):
            board[i][j] >>= 1
    return board


