void gameOfLife(vector<vector<int>>& board) {
    int m = board.size(), n = board[0].size();
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j) {
            int c = 0;
            for (int x = max(0, i - 1); x <= min(m - 1, i + 1); ++x)
                for (int y = max(0, j - 1); y <= min(n - 1, j + 1); ++y)
                    if (x != i || y != j) c += board[x][y] & 1;
            if (c == 3 || ((board[i][j] & 1) && c == 2)) board[i][j] |= 2;
