from collections import defaultdict


def sub_collapse(M, target):
    m, n = len(M), len(M[0])
    total = 0
    for top in range(m):
        col = [0] * n
        for bottom in range(top, m):
            for j in range(n):
                col[j] += M[bottom][j]
            cnt = defaultdict(int)
            cnt[0] = 1
            pre = 0
            for v in col:
                pre += v
                total += cnt[pre - target]
                cnt[pre] += 1
    return total


