``` {.python .cell-code}
def dsum_two(a):
    n = len(a)
    main = sum(a[i][i] for i in range(n))
    anti = sum(a[i][n - 1 - i] for i in range(n))
    overlap = a[n // 2][n // 2] if n % 2 == 1 else 0
    return main + anti - overlap


assert dsum_two([[1, 2, 3], [4, 5, 6], [7, 8, 9]]) == 25
