int dsumTwo(vector<vector<int>>& a) {
    int n = a.size();
    int main = 0, anti = 0;
    for (int i = 0; i < n; ++i) main += a[i][i];
    for (int i = 0; i < n; ++i) anti += a[i][n - 1 - i];
    int overlap = (n % 2 == 1) ? a[n / 2][n / 2] : 0;
    return main + anti - overlap;
}
```

