##### Python

::: {#14ba000d .cell execution_count=100}
``` {.python .cell-code}
def artem_brute(a):
    n, m = len(a), len(a[0])
    b = [[0] * m for _ in range(n)]

    def go(k):
        if k == n * m:
            return True
        i, j = divmod(k, m)
        for d in (0, 1):
            v = a[i][j] + d
            if (i and b[i - 1][j] == v) or (j and b[i][j - 1] == v):
                continue
            b[i][j] = v
            if go(k + 1):
                return True
        return False

    assert go(0)
    return b


def artem_ok(a, b):
    n, m = len(a), len(a[0])
    for i in range(n):
        for j in range(m):
            if b[i][j] - a[i][j] not in (0, 1):
                return False
            if i + 1 < n and b[i][j] == b[i + 1][j]:
                return False
            if j + 1 < m and b[i][j] == b[i][j + 1]:
                return False
    return True


assert artem_ok([[2, 2], [3, 2]], artem_brute([[2, 2], [3, 2]]))
