struct ArtemBrute {
    int n, m;
    vector<vector<long long>> a, b;
    bool go(int k) {
        if (k == n * m) return true;
        int i = k / m, j = k % m;
        for (int d = 0; d < 2; ++d) {
            long long v = a[i][j] + d;
            if ((i && b[i - 1][j] == v) || (j && b[i][j - 1] == v)) continue;
            b[i][j] = v;
            if (go(k + 1)) return true;
        }
        return false;
    }
};
